<script setup lang="ts">withDefaults(defineProps<{ open: boolean; title: string; description: string; confirmText?: string; submitting?: boolean }>(), { confirmText: 'Delete', submitting: false }); const emit = defineEmits<{ cancel: []; confirm: [] }>()</script>
<template><div v-if="open" class="confirm-backdrop" role="presentation" @click.self="!submitting && emit('cancel')"><section class="confirm-dialog" role="alertdialog" aria-modal="true" :aria-label="title"><h2>{{ title }}</h2><p>{{ description }}</p><div><button type="button" class="button button--outline" :disabled="submitting" @click="emit('cancel')">Cancel</button><button type="button" class="button button--danger" :disabled="submitting" @click="emit('confirm')">{{ submitting ? 'Working…' : confirmText }}</button></div></section></div></template>
